import type { BankQuestion } from "@/lib/bank";

/** Electrochemistry and Chemical Kinetics (Chemistry (JEE/NEET)): 129 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"chem-electrochemistry-1","question":"The SI-derived unit commonly used for molar conductivity is:","options":["Ω cm","Ω⁻¹ cm⁻¹ mol","S cm⁻¹","S cm² mol⁻¹"],"answer":3,"explanation":"Molar conductivity Λm = κ × 1000/c, where κ (conductivity) is in S cm⁻¹ and c in mol L⁻¹, giving S cm² mol⁻¹ (SI: S m² mol⁻¹).","difficulty":"easy","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-2","question":"In a galvanic cell, oxidation takes place at the:","options":["Cathode, which is the positive electrode","Anode, which is the negative electrode","Salt bridge","Anode, which is the positive electrode"],"answer":1,"explanation":"In a galvanic (voltaic) cell the anode is the site of oxidation and carries a negative sign because it releases electrons into the external circuit. In an electrolytic cell the anode is positive.","difficulty":"easy","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-3","question":"The half-life of a first-order reaction:","options":["Is directly proportional to the initial concentration","Is inversely proportional to the initial concentration","Is independent of the initial concentration","Doubles when the initial concentration doubles"],"answer":2,"explanation":"For a first-order reaction t½ = 0.693/k, which contains no concentration term. A zero-order t½ is proportional to [A]₀; a second-order t½ is inversely proportional to [A]₀.","difficulty":"easy","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-4","question":"The quantity of electricity required to deposit 1 mol of aluminium from molten Al₂O₃ is:","options":["1 F","2 F","3 F","6 F"],"answer":2,"explanation":"Al³⁺ + 3e⁻ → Al, so each mole of Al needs 3 mol of electrons = 3 F = 3 × 96500 C ≈ 2.9 × 10⁵ C.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-5","question":"Given E°(Zn²⁺/Zn) = −0.76 V and E°(Cu²⁺/Cu) = +0.34 V, the standard EMF of the cell Zn | Zn²⁺(1 M) || Cu²⁺(1 M) | Cu is:","options":["+1.10 V","−1.10 V","−0.42 V","+0.42 V"],"answer":0,"explanation":"E°cell = E°(cathode) − E°(anode) = 0.34 − (−0.76) = +1.10 V. Adding the two values without attention to sign gives the wrong 0.42 V.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-6","question":"The unit of the rate constant of a second-order reaction is:","options":["s⁻¹","mol L⁻¹ s⁻¹","L mol⁻¹ s⁻¹","L² mol⁻² s⁻¹"],"answer":2,"explanation":"Units of k are (mol L⁻¹) raised to the power (1 − n), times s⁻¹. For n = 2 this is L mol⁻¹ s⁻¹. s⁻¹ is first order, mol L⁻¹ s⁻¹ is zero order and L² mol⁻² s⁻¹ is third order.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-7","question":"Limiting molar conductivities (S cm² mol⁻¹) at 298 K: CH₃COONa = 91, HCl = 426, NaCl = 126. The limiting molar conductivity of acetic acid is:","options":["643","391","209","335"],"answer":1,"explanation":"By Kohlrausch's law Λ°m(CH₃COOH) = Λ°m(CH₃COONa) + Λ°m(HCl) − Λ°m(NaCl) = 91 + 426 − 126 = 391 S cm² mol⁻¹. The Na⁺ and Cl⁻ contributions cancel.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-8","question":"The half-life of a first-order reaction is 20 min. The time required for 75% completion is:","options":["30 min","40 min","60 min","80 min"],"answer":1,"explanation":"75% completion means the concentration falls to 25% = (1/2)², i.e. two half-lives: 2 × 20 = 40 min.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-9","question":"Which statement about the effect of a catalyst on a reaction is correct?","options":["A catalyst provides an alternative pathway with lower activation energy","A catalyst increases the enthalpy change of the reaction","A catalyst increases the activation energy of the reaction","A catalyst changes the equilibrium constant in favour of products"],"answer":0,"explanation":"A catalyst lowers the activation energy by providing a different mechanism; it does not change ΔH or the equilibrium constant, only how fast equilibrium is reached.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-10","question":"For the cell Zn | Zn²⁺(0.1 M) || Cu²⁺(0.01 M) | Cu at 298 K (E°cell = 1.10 V), the cell EMF is:","options":["1.04 V","1.13 V","1.10 V","1.07 V"],"answer":3,"explanation":"Ecell = E° − (0.0591/2) log([Zn²⁺]/[Cu²⁺]) = 1.10 − 0.02955 × log(0.1/0.01) = 1.10 − 0.0296 × 1 ≈ 1.07 V. The lower Cu²⁺ concentration lowers the EMF.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-11","question":"A charge of 9650 C is passed through aqueous CuSO₄. The mass of copper deposited at the cathode is (Cu = 63.5):","options":["6.35 g","3.18 g","1.59 g","0.635 g"],"answer":1,"explanation":"Moles of electrons = 9650/96500 = 0.1 mol. Cu²⁺ + 2e⁻ → Cu needs 2 mol e⁻ per mol Cu, so 0.05 mol Cu = 0.05 × 63.5 = 3.18 g. Forgetting the factor of 2 gives 6.35 g.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-12","question":"A conductivity cell filled with 0.1 M KCl (κ = 0.0129 S cm⁻¹) has a resistance of 100 Ω. The cell constant is:","options":["0.129 cm⁻¹","1.29 cm⁻¹","12.9 cm⁻¹","7.75 cm⁻¹"],"answer":1,"explanation":"κ = (cell constant)/R, so cell constant = κ × R = 0.0129 × 100 = 1.29 cm⁻¹. The same cell can then be used to find κ of any other solution from its resistance.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-13","question":"The rate constant of a first-order reaction is 2.31 × 10⁻³ s⁻¹. The time needed for the reactant concentration to fall from 0.8 M to 0.1 M is:","options":["1200 s","300 s","600 s","900 s"],"answer":3,"explanation":"t½ = 0.693/(2.31 × 10⁻³) = 300 s. 0.8 → 0.4 → 0.2 → 0.1 M is three half-lives, so t = 3 × 300 = 900 s.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-14","question":"The rate constant of a reaction doubles when the temperature is raised from 300 K to 310 K. The activation energy is approximately (R = 8.314 J K⁻¹ mol⁻¹, log 2 = 0.301):","options":["26.8 kJ mol⁻¹","53.6 kJ mol⁻¹","107 kJ mol⁻¹","5.36 kJ mol⁻¹"],"answer":1,"explanation":"log(k₂/k₁) = (Ea/2.303R) × (T₂ − T₁)/(T₁T₂). Ea = 2.303 × 8.314 × 0.301 × (300 × 310)/10 = 5.764 × 9300 ≈ 53600 J ≈ 53.6 kJ mol⁻¹.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-15","question":"The standard Gibbs energy change for the Daniell cell reaction Zn + Cu²⁺ → Zn²⁺ + Cu (E°cell = 1.10 V, F = 96500 C mol⁻¹) is:","options":["−106.2 kJ mol⁻¹","−212.3 kJ mol⁻¹","+212.3 kJ mol⁻¹","−424.6 kJ mol⁻¹"],"answer":1,"explanation":"ΔG° = −nFE° = −2 × 96500 × 1.10 = −212300 J ≈ −212.3 kJ mol⁻¹. Two electrons are transferred per Zn atom, so n = 2.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-16","question":"The molar conductivity of 0.01 M acetic acid is 39.1 S cm² mol⁻¹ and its limiting molar conductivity is 391 S cm² mol⁻¹. Its dissociation constant is approximately:","options":["1.0 × 10⁻⁵","1.0 × 10⁻³","1.11 × 10⁻⁵","1.11 × 10⁻⁴"],"answer":3,"explanation":"α = Λm/Λ°m = 39.1/391 = 0.1. Ka = cα²/(1 − α) = 0.01 × 0.01/0.9 ≈ 1.11 × 10⁻⁴. Ignoring the (1 − α) term gives 1.0 × 10⁻⁴, which is not among the options.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-17","question":"For a reaction A + B → products, the rate doubles when [A] is doubled and becomes four times when [B] is doubled. If both [A] and [B] are doubled together, the rate becomes:","options":["2 times","4 times","8 times","16 times"],"answer":2,"explanation":"Rate = k[A][B]² (first order in A, second in B, overall third). Doubling both gives 2 × 2² = 8 times the original rate.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-18","question":"Given E°: F₂/F⁻ = 2.87 V, Cl₂/Cl⁻ = 1.36 V, Br₂/Br⁻ = 1.09 V, I₂/I⁻ = 0.54 V. Which reaction is spontaneous under standard conditions?","options":["I₂ + 2Cl⁻ → 2I⁻ + Cl₂","Br₂ + 2Cl⁻ → 2Br⁻ + Cl₂","I₂ + 2Br⁻ → 2I⁻ + Br₂","Cl₂ + 2Br⁻ → 2Cl⁻ + Br₂"],"answer":3,"explanation":"A halogen with a higher reduction potential oxidises the halide of a halogen with a lower one. Cl₂ (1.36 V) oxidises Br⁻ (E°cell = 1.36 − 1.09 = +0.27 V). The other options would need a weaker oxidant to oxidise a stronger one, giving negative E°cell.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-19","question":"The EMF of the cell Pt | H₂(1 atm) | H⁺(pH = 2) || H⁺(1 M) | H₂(1 atm) | Pt at 298 K is:","options":["−0.118 V","+0.059 V","+0.118 V","+0.236 V"],"answer":2,"explanation":"E(H⁺/H₂) = −0.0591 × pH. The anode (pH 2) has E = −0.118 V; the cathode (1 M, pH 0) has E = 0. Ecell = 0 − (−0.118) = +0.118 V: hydrogen is oxidised where H⁺ is dilute and H⁺ is reduced where it is concentrated.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-20","question":"The EMF of the concentration cell Cu | Cu²⁺(0.001 M) || Cu²⁺(0.1 M) | Cu at 298 K is:","options":["0.118 V","0","0.0296 V","0.0591 V"],"answer":3,"explanation":"E° = 0 for a concentration cell. Ecell = (0.0591/2) log([Cu²⁺]cathode/[Cu²⁺]anode) = 0.02955 × log(0.1/0.001) = 0.02955 × 2 = 0.0591 V. Using n = 1 gives the wrong 0.118 V.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-21","question":"How many of the following statements are correct? (i) On dilution, conductivity of an electrolyte solution decreases while molar conductivity increases. (ii) Λ°m of a weak electrolyte is obtained by extrapolating the Λm versus √c plot to zero concentration. (iii) In the Daniell cell, electrons flow from zinc to copper through the external wire. (iv) In a discharging lead storage battery, H₂SO₄ is consumed and the density of the electrolyte falls.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (iii) and (iv) are correct. (ii) is wrong: the √c extrapolation (Debye–Hückel–Onsager) works only for strong electrolytes; for weak electrolytes Λm rises steeply near zero concentration, so Λ°m is obtained from Kohlrausch's law of independent migration.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-22","question":"A current of 2 A is passed for 965 s through aqueous AgNO₃ and aqueous CuSO₄ connected in series. The mass of copper deposited is (Cu = 63.5, Ag = 108, F = 96500 C mol⁻¹):","options":["0.635 g","0.3175 g","1.27 g","2.16 g"],"answer":0,"explanation":"Q = 2 × 965 = 1930 C = 0.02 mol e⁻. Cu²⁺ + 2e⁻ → Cu gives 0.01 mol = 0.635 g of Cu (while Ag⁺ + e⁻ → Ag gives 0.02 mol = 2.16 g of Ag in the other cell). The same charge passes through both cells in series.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-23","question":"The gas-phase first-order reaction A(g) → 2B(g) + C(g) starts with pure A at 100 mm Hg. After 10 min the total pressure is 160 mm Hg. The rate constant is (log 1.4286 = 0.155):","options":["0.0155 min⁻¹","0.0357 min⁻¹","0.0470 min⁻¹","0.0693 min⁻¹"],"answer":1,"explanation":"If x mm of A has reacted, total pressure = (100 − x) + 2x + x = 100 + 2x = 160, so x = 30 and P(A) = 70 mm. k = (2.303/t) log(P₀/P(A)) = (2.303/10) × log(100/70) = 0.2303 × 0.155 ≈ 0.0357 min⁻¹.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-24","question":"A plot of ln k against 1/T for a reaction is a straight line with slope −1.0 × 10⁴ K. The activation energy is (R = 8.314 J K⁻¹ mol⁻¹):","options":["831 kJ mol⁻¹","8.31 kJ mol⁻¹","41.6 kJ mol⁻¹","83.1 kJ mol⁻¹"],"answer":3,"explanation":"From ln k = ln A − Ea/(RT), the slope of ln k versus 1/T is −Ea/R. Ea = 1.0 × 10⁴ × 8.314 = 83140 J ≈ 83.1 kJ mol⁻¹. If the plot were log k versus 1/T, the slope would be −Ea/(2.303R).","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-25","question":"Assertion (A): E°cell of the Daniell cell remains 1.10 V even if the cell reaction is written as 2Zn + 2Cu²⁺ → 2Zn²⁺ + 2Cu. Reason (R): Electrode potential is an intensive property, whereas ΔG° is extensive.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Doubling the equation doubles n and ΔG° (−nFE°) but E° = −ΔG°/(nF) is unchanged, because potential does not depend on the amount of substance. R is the exact reason for A.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-26","question":"Match the reaction type with the correct statement. (A) Zero order; (B) First order; (C) Second order; (D) Pseudo-first order. (p) t½ ∝ 1/[A]₀; (q) Acid-catalysed hydrolysis of an ester in excess water; (r) t½ ∝ [A]₀; (s) t½ is independent of [A]₀.","options":["A–r, B–s, C–p, D–q","A–s, B–r, C–p, D–q","A–r, B–p, C–s, D–q","A–p, B–s, C–r, D–q"],"answer":0,"explanation":"Zero order: t½ = [A]₀/2k (∝ [A]₀). First order: t½ = 0.693/k (independent). Second order: t½ = 1/(k[A]₀). Ester hydrolysis in large excess of water is a bimolecular reaction that behaves as first order because [H₂O] is effectively constant.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-27","question":"For a cell reaction involving 2 electrons, E°cell = 0.1182 V at 298 K. The equilibrium constant of the cell reaction is:","options":["10²","10⁴","10⁸","10⁻⁴"],"answer":1,"explanation":"At equilibrium Ecell = 0, so E° = (0.0591/n) log K. log K = nE°/0.0591 = 2 × 0.1182/0.0591 = 4, hence K = 10⁴. Forgetting n = 2 gives 10².","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-28","question":"The half-life of a first-order reaction is 10 min at 300 K and 2.5 min at 320 K. The activation energy is approximately (R = 8.314 J K⁻¹ mol⁻¹, log 4 = 0.602):","options":["110.6 kJ mol⁻¹","13.8 kJ mol⁻¹","27.7 kJ mol⁻¹","55.3 kJ mol⁻¹"],"answer":3,"explanation":"k ∝ 1/t½, so k₂/k₁ = 10/2.5 = 4. Ea = 2.303 R log(k₂/k₁) × T₁T₂/(T₂ − T₁) = 2.303 × 8.314 × 0.602 × (300 × 320)/20 = 11.53 × 4800 ≈ 55300 J ≈ 55.3 kJ mol⁻¹.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-29","question":"How many of the following statements are correct? (i) In the H₂–O₂ fuel cell, oxygen is reduced at the cathode to give OH⁻ ions. (ii) The mercury cell gives a nearly constant voltage because its overall reaction involves no ion whose concentration changes. (iii) In rusting, oxygen is reduced at the cathodic region of the iron surface in the presence of H⁺. (iv) The dry (Leclanché) cell is a secondary cell that can be recharged.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iii) are correct. (iv) is wrong: the dry cell is a primary cell; the lead storage battery and Ni–Cd cell are secondary (rechargeable) cells.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-30","question":"Which of the following does NOT change the rate constant of a reaction?","options":["Changing the solvent","Raising the temperature","Adding a catalyst","Increasing the concentration of a reactant"],"answer":3,"explanation":"The rate constant k depends on temperature, catalyst and the medium (Arrhenius factors), but not on concentration. Increasing concentration raises the rate, not k.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-31","question":"The main function of a salt bridge in a galvanic cell is to:","options":["Supply electrons to the cathode","Complete the circuit and keep both half-cell solutions electrically neutral","Increase the standard EMF of the cell","Prevent oxidation at the anode"],"answer":1,"explanation":"Ions migrate from the salt bridge to balance the charge build-up in each half-cell; without it the current stops almost at once.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-32","question":"By Kohlrausch's law, the limiting molar conductivity of Al₂(SO₄)₃ is:","options":["2λ°(Al³⁺) + 3λ°(SO₄²⁻)","(λ°(Al³⁺) + λ°(SO₄²⁻))/5","3λ°(Al³⁺) + 2λ°(SO₄²⁻)","λ°(Al³⁺) + λ°(SO₄²⁻)"],"answer":0,"explanation":"Λ°m = ν₊λ°₊ + ν₋λ°₋ where ν are the numbers of ions per formula unit: 2 Al³⁺ and 3 SO₄²⁻.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-33","question":"In the rusting of iron, the reaction at the anodic region is:","options":["O₂ + 4H⁺ + 4e⁻ → 2H₂O","2H⁺ + 2e⁻ → H₂","Fe²⁺ → Fe³⁺ + e⁻ only","Fe → Fe²⁺ + 2e⁻"],"answer":3,"explanation":"Iron is oxidised to Fe²⁺ at the anode; oxygen is reduced at the cathodic region, and Fe²⁺ is later oxidised to hydrated Fe₂O₃ (rust).","difficulty":"moderate","source":"NEET"},
  {"id":"chem-electrochemistry-34","question":"For a zero-order reaction, the half-life is:","options":["Proportional to the square of the initial concentration","Independent of the initial concentration","Directly proportional to the initial concentration","Inversely proportional to the initial concentration"],"answer":2,"explanation":"t½ = [A]₀/2k for zero order. For first order t½ is independent of [A]₀; for second order it is inversely proportional.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-35","question":"Aqueous NaCl is electrolysed using inert electrodes. The products at the cathode and anode respectively are:","options":["H₂ and Cl₂","Na and Cl₂","Na and O₂","H₂ and O₂"],"answer":0,"explanation":"Water is reduced in preference to Na⁺ at the cathode (H₂ + OH⁻). At the anode Cl⁻ is oxidised rather than water because of the overpotential for O₂; NaOH remains in solution.","difficulty":"hard","source":"NEET"},
  {"id":"chem-electrochemistry-36","question":"Given E°(Fe³⁺/Fe²⁺) = +0.77 V and E°(Fe²⁺/Fe) = −0.44 V, the value of E°(Fe³⁺/Fe) is:","options":["+0.33 V","+1.21 V","−0.037 V","−0.11 V"],"answer":2,"explanation":"Add ΔG° values, not potentials: −3F·E° = −1F(0.77) − 2F(−0.44) → 3E° = 0.77 − 0.88 = −0.11, E° = −0.037 V. Simply adding the potentials (0.33 V) is the trap.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-37","question":"For a first-order reaction, the time needed for 99.9% completion is about how many times its half-life?","options":["100","10","2","7"],"answer":1,"explanation":"t = (2.303/k) log(1000) = 3 × 2.303/k = 6.909/k; t½ = 0.693/k. Ratio ≈ 10.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-38","question":"During the discharge of a lead storage battery:","options":["PbO₂ is formed at the anode","Sulphuric acid is consumed and the density of the electrolyte falls","Lead is deposited at the cathode","Sulphuric acid is produced and its density rises"],"answer":1,"explanation":"Overall: Pb + PbO₂ + 2H₂SO₄ → 2PbSO₄ + 2H₂O. Acid is used up and water formed, so the density drops; PbSO₄ forms at both electrodes.","difficulty":"hard","source":"NEET"},
  {"id":"chem-electrochemistry-39","question":"How many of the following statements are correct? (A) The molar conductivity of a strong electrolyte varies linearly with √c at low concentrations. (B) Λ°m of a weak electrolyte is found by extrapolating its Λm versus √c plot to zero concentration. (C) The conductivity of an electrolytic solution increases with temperature. (D) The cell constant has the unit cm.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"A (Debye–Hückel–Onsager) and C are correct. B is wrong: Λm of a weak electrolyte rises steeply at low c, so Kohlrausch's law is used instead. D is wrong: cell constant = l/A, unit cm⁻¹.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-40","question":"A catalyst lowers the activation energy of a reaction from 100 kJ mol⁻¹ to 80 kJ mol⁻¹ at 300 K, with the frequency factor unchanged. The rate increases by a factor of about (R = 8.314 J K⁻¹ mol⁻¹):","options":["20","1.25","3 × 10³","8"],"answer":2,"explanation":"k₂/k₁ = e^(ΔEa/RT) = e^(20 000/(8.314 × 300)) = e^8.02 ≈ 3.0 × 10³. 1.25 is just 100/80.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-41","question":"A current of 0.5 A is passed through aqueous AgNO₃. The time needed to deposit 1.08 g of silver (Ag = 108, F = 96 500 C mol⁻¹) is:","options":["3860 s","1930 s","965 s","193 s"],"answer":1,"explanation":"n(Ag) = 0.01 mol, needing 0.01 F = 965 C. t = Q/I = 965/0.5 = 1930 s.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-42","question":"In a first-order reaction 10% of the reactant is consumed in 20 minutes. The time after which 19% of the original reactant will have been consumed is:","options":["40 min","20 min","38 min","36 min"],"answer":0,"explanation":"After 20 min, 0.90 remains; after another 20 min, 0.90 × 0.90 = 0.81 remains, i.e. 19% consumed. Equal times remove equal fractions in first-order kinetics.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-43","question":"Assertion (A): The rate of a reaction increases with temperature mainly because the total number of collisions increases. Reason (R): A 10 K rise in temperature roughly doubles the fraction of molecules with energy equal to or greater than the activation energy.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"A is false: collision frequency rises only a few per cent per 10 K; the main cause is the larger fraction of effective (energetic) collisions. R is true and is the real reason.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-44","question":"For the cell Fe | Fe²⁺(0.001 M) || H⁺(1 M) | H₂(1 bar) | Pt at 298 K, with E°(Fe²⁺/Fe) = −0.44 V, the EMF is about:","options":["0.62 V","0.44 V","0.35 V","0.53 V"],"answer":3,"explanation":"Fe + 2H⁺ → Fe²⁺ + H₂, E° = 0.44 V. E = 0.44 − (0.0591/2) log(0.001/1²) = 0.44 + 0.0887 ≈ 0.53 V. A dilute product makes the cell EMF larger.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-45","question":"Which statement about order and molecularity is INCORRECT?","options":["Acid hydrolysis of an ester in excess water is a pseudo-first-order reaction","Molecularity of a reaction can be zero or fractional","Molecularity is defined only for elementary reactions","Order of a reaction can be zero or fractional"],"answer":1,"explanation":"Molecularity counts the species colliding in an elementary step, so it is always a whole number (1, 2 or rarely 3). Order is experimental and can be zero or fractional.","difficulty":"very-hard","source":"NEET"},
  {"id": "chem-electrochemistry-46", "question": "One faraday is the electric charge carried by:", "options": ["One electron", "One coulomb per second", "One mole of electrons, about 96 500 C", "One mole of protons, about 9650 C"], "answer": 2, "explanation": "1 F = N_A × e = 6.022 × 10²³ × 1.602 × 10⁻¹⁹ C ≈ 96 500 C, the charge on one mole of electrons.", "difficulty": "easy", "source": "NEET"},
  {"id": "chem-electrochemistry-47", "question": "The decay of a radioactive nucleus follows kinetics of order:", "options": ["Zero", "First", "Second", "Third"], "answer": 1, "explanation": "Radioactive decay is first order: the rate is proportional to the number of nuclei present, and the half-life is independent of the amount.", "difficulty": "easy", "source": "NEET"},
  {"id": "chem-electrochemistry-48", "question": "The SI unit of conductivity (κ) is:", "options": ["S m² mol⁻¹", "Ω m", "S", "S m⁻¹"], "answer": 3, "explanation": "κ = (1/R)(l/A), so its unit is S × m/m² = S m⁻¹. S m² mol⁻¹ is the unit of molar conductivity; Ω m is the unit of resistivity, its reciprocal.", "difficulty": "moderate", "source": "NEET"},
  {"id": "chem-electrochemistry-49", "question": "For 2N₂O₅(g) → 4NO₂(g) + O₂(g), N₂O₅ disappears at a rate of 0.02 mol L⁻¹ s⁻¹ at some instant. The rate of formation of NO₂ at that instant is:", "options": ["0.04 mol L⁻¹ s⁻¹", "0.02 mol L⁻¹ s⁻¹", "0.08 mol L⁻¹ s⁻¹", "0.01 mol L⁻¹ s⁻¹"], "answer": 0, "explanation": "−½ d[N₂O₅]/dt = ¼ d[NO₂]/dt, so d[NO₂]/dt = 2 × 0.02 = 0.04 mol L⁻¹ s⁻¹. 0.01 is the rate of formation of O₂.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-electrochemistry-50", "question": "Which of the following metals can liberate hydrogen gas from dilute hydrochloric acid? (E°: Cu²⁺/Cu = +0.34 V, Ag⁺/Ag = +0.80 V, Au³⁺/Au = +1.50 V, Zn²⁺/Zn = −0.76 V)", "options": ["Cu", "Ag", "Au", "Zn"], "answer": 3, "explanation": "A metal with a negative standard reduction potential (below hydrogen in the series) reduces H⁺ to H₂. Only Zn has E° < 0; Cu, Ag and Au lie above hydrogen.", "difficulty": "moderate", "source": "NEET"},
  {"id": "chem-electrochemistry-51", "question": "A zero-order reaction has rate constant 0.02 mol L⁻¹ min⁻¹. If the initial concentration is 0.5 mol L⁻¹, the reaction is complete after:", "options": ["12.5 min", "50 min", "25 min", "34.7 min"], "answer": 2, "explanation": "For zero order [A] = [A]₀ − kt, so complete reaction ([A] = 0) takes t = [A]₀/k = 0.5/0.02 = 25 min. 12.5 min is the half-life.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-electrochemistry-52", "question": "Iron is protected from rusting by coating it with zinc (galvanising). Zinc protects iron even when the coating is scratched, because:", "options": ["Zinc forms an alloy with iron that does not rust", "Zinc is more easily oxidised than iron and corrodes in preference to it (sacrificial protection)", "Zinc is less reactive than iron", "Zinc reduces rust back to iron"], "answer": 1, "explanation": "Zinc has a more negative reduction potential (−0.76 V) than iron (−0.44 V), so it acts as the anode and is oxidised instead of iron. A less reactive coating such as tin protects only while it is unbroken.", "difficulty": "moderate", "source": "NEET"},
  {"id": "chem-electrochemistry-53", "question": "E° for MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O is 1.51 V. At 298 K, the electrode potential at pH = 1 with [MnO₄⁻] = [Mn²⁺] is about:", "options": ["1.60 V", "1.42 V", "1.45 V", "1.51 V"], "answer": 1, "explanation": "E = E° − (0.059/5) log{[Mn²⁺]/([MnO₄⁻][H⁺]⁸)} = 1.51 − (0.059/5) × 8 = 1.51 − 0.094 = 1.42 V. The potential depends strongly on pH because [H⁺] appears to the eighth power.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-electrochemistry-54", "question": "The volume of O₂ gas at STP liberated at the anode when 1 faraday of electricity is passed through acidified water is:", "options": ["11.2 L", "22.4 L", "5.6 L", "2.8 L"], "answer": 2, "explanation": "2H₂O → O₂ + 4H⁺ + 4e⁻: 4 F give 1 mol O₂ (22.4 L), so 1 F gives 5.6 L. 11.2 L is the volume of H₂ produced at the cathode by 1 F.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-electrochemistry-55", "question": "For a reaction with activation energy 28.72 kJ mol⁻¹ at 300 K, the fraction of molecules having energy equal to or greater than Ea is about (2.303 × 8.314 × 300 = 5744 J mol⁻¹):", "options": ["1 × 10⁻⁴", "1 × 10⁻⁶", "5 × 10⁻⁵", "1 × 10⁻⁵"], "answer": 3, "explanation": "Fraction = e^(−Ea/RT) = 10^(−Ea/2.303RT) = 10^(−28 720/5744) = 10⁻⁵.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-electrochemistry-56", "question": "The half-life of a reaction becomes four times longer when the initial concentration of the reactant is halved. The order of the reaction is:", "options": ["First", "Second", "Third", "Zero"], "answer": 2, "explanation": "t½ ∝ [A]₀^(1 − n). Halving [A]₀ multiplies t½ by 2^(n − 1) = 4, so n − 1 = 2 and n = 3. For second order t½ would only double.", "difficulty": "hard", "source": "JEE Advanced pattern"},
  {"id": "chem-electrochemistry-57", "question": "The conductivity of a 0.02 M KCl solution is 0.0025 S cm⁻¹. Its molar conductivity is:", "options": ["125 S cm² mol⁻¹", "12.5 S cm² mol⁻¹", "1.25 × 10⁻⁴ S cm² mol⁻¹", "250 S cm² mol⁻¹"], "answer": 0, "explanation": "Λm = κ × 1000/M = 0.0025 × 1000/0.02 = 125 S cm² mol⁻¹. The factor 1000 converts litres to cm³.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-electrochemistry-58", "question": "When concentrated sulphuric acid is electrolysed with platinum electrodes, the main anode reaction forms:", "options": ["H₂", "SO₂", "O₂", "Peroxodisulphate ions, S₂O₈²⁻"], "answer": 3, "explanation": "With dilute H₂SO₄, water is oxidised to O₂ at the anode. At high concentration, 2SO₄²⁻ → S₂O₈²⁻ + 2e⁻ (E° = 1.96 V) is preferred despite its higher potential.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-electrochemistry-59", "question": "The rate constant of a reaction at 300 K is k, and its temperature coefficient (ratio of rate constants for a 10 K rise) is 2. Its rate constant at 340 K is:", "options": ["8k", "16k", "4k", "32k"], "answer": 1, "explanation": "A 40 K rise is four 10 K steps: k(340) = 2⁴k = 16k.", "difficulty": "hard", "source": "NEET"},
  {"id": "chem-electrochemistry-60", "question": "How many of the following statements about the collision theory of reaction rates are correct? (A) A collision leads to reaction only if the molecules have at least the threshold energy and the proper orientation. (B) The theory treats reacting molecules as hard spheres. (C) The steric (probability) factor P accounts for the need for proper orientation. (D) A catalyst increases the enthalpy change of the reaction.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(A), (B) and (C) are part of collision theory (rate = P Z e^(−Ea/RT)). (D) is false: a catalyst provides a path with lower Ea but leaves ΔH unchanged. Three are correct.", "difficulty": "very-hard", "source": "NEET"},
  {"id": "chem-electrochemistry-61", "question": "Aluminium is produced by electrolysis of molten Al₂O₃. A current of 965 A is passed for 1 hour at 80% current efficiency. The mass of aluminium deposited is (Al = 27, F = 96 500 C mol⁻¹):", "options": ["324 g", "259.2 g", "777.6 g", "86.4 g"], "answer": 1, "explanation": "Charge = 965 × 3600 = 3.474 × 10⁶ C; useful charge = 0.8 × that = 2.779 × 10⁶ C = 28.8 mol e⁻. Al³⁺ needs 3 e⁻, so Al = 9.6 mol = 259.2 g. 324 g assumes 100% efficiency.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-electrochemistry-62", "question": "Given E°(Ag⁺/Ag) = 0.80 V and E°(AgCl/Ag, Cl⁻) = 0.22 V at 298 K, the solubility product of AgCl is about:", "options": ["1.5 × 10⁻⁵", "1 × 10⁻²⁰", "1.5 × 10⁻¹⁰", "6.7 × 10⁹"], "answer": 2, "explanation": "AgCl + e⁻ → Ag + Cl⁻ (0.22 V) minus Ag⁺ + e⁻ → Ag (0.80 V) gives AgCl → Ag⁺ + Cl⁻, E° = −0.58 V. log Ksp = nE°/0.059 = −0.58/0.059 = −9.83, so Ksp ≈ 1.5 × 10⁻¹⁰.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-electrochemistry-63", "question": "A reactant A decomposes by two parallel first-order reactions: A → B (k₁ = 3 × 10⁻³ s⁻¹) and A → C (k₂ = 1 × 10⁻³ s⁻¹). The half-life of A and the percentage of B in the products are:", "options": ["231 s and 75%", "173 s and 25%", "693 s and 75%", "173 s and 75%"], "answer": 3, "explanation": "A disappears with k = k₁ + k₂ = 4 × 10⁻³ s⁻¹, so t½ = 0.693/0.004 = 173 s. The products form in the ratio k₁ : k₂ = 3 : 1, so B = 75%. 231 s uses k₁ alone.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-electrochemistry-64", "question": "Assertion (A): When aqueous NaCl is electrolysed, Cl₂ rather than O₂ is liberated at the anode, although the standard potential for oxidising water is lower. Reason (R): The oxidation of water to O₂ has a high overpotential.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "E° for O₂/H₂O (1.23 V) is lower than for Cl₂/Cl⁻ (1.36 V), but O₂ evolution is kinetically slow and needs extra voltage (overpotential), so Cl₂ forms. R correctly explains A.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-electrochemistry-65", "question": "Match the cell (Column I) with its description (Column II). (a) Leclanché (dry) cell, (b) Mercury cell, (c) Lead storage battery, (d) Nickel–cadmium cell. (1) Paste of KOH and ZnO as electrolyte, about 1.35 V constant; (2) About 38% H₂SO₄ as electrolyte; (3) Paste of NH₄Cl and ZnCl₂, about 1.5 V; (4) Rechargeable, with longer life than the lead battery but costlier.", "options": ["a-1, b-3, c-2, d-4", "a-3, b-1, c-2, d-4", "a-3, b-2, c-1, d-4", "a-3, b-1, c-4, d-2"], "answer": 1, "explanation": "The dry cell uses an NH₄Cl/ZnCl₂ paste (≈1.5 V); the mercury cell uses a KOH–ZnO paste and gives a steady 1.35 V; the lead storage battery uses 38% H₂SO₄; Ni–Cd is a long-life rechargeable cell. So a-3, b-1, c-2, d-4.", "difficulty": "very-hard", "source": "NEET"},
  {"id": "chem-electrochemistry-66", "question": "For the second-order reaction 2A → P with −d[A]/dt = k[A]² and k = 0.5 L mol⁻¹ min⁻¹, the time for [A] to fall from 0.2 M to 0.05 M is:", "options": ["30 min", "15 min", "60 min", "2.77 min"], "answer": 0, "explanation": "Integrated second-order law: 1/[A] − 1/[A]₀ = kt → 20 − 5 = 0.5t → t = 30 min. 2.77 min wrongly applies the first-order formula (ln 4/0.5).", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-electrochemistry-67", "question": "How many of the following statements are correct? (A) If E°cell is positive, ΔG° of the cell reaction is negative. (B) In a galvanic cell the cathode is the negative electrode. (C) By convention, the standard hydrogen electrode is assigned a potential of zero at all temperatures. (D) A galvanic cell converts electrical energy into chemical energy.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "(A) true, since ΔG° = −nFE°. (B) false: in a galvanic cell the cathode is positive. (C) true. (D) false: a galvanic cell converts chemical energy into electrical energy; an electrolytic cell does the reverse. Two are correct.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-electrochemistry-68", "question": "For a first-order reaction, which of the following plots is NOT a straight line?", "options": ["[A] against t", "ln[A] against t", "log([A]₀/[A]) against t", "t½ against [A]₀"], "answer": 0, "explanation": "[A] = [A]₀e^(−kt) falls exponentially, so [A] against t is a curve. ln[A] against t (slope −k) and log([A]₀/[A]) against t (slope k/2.303) are straight lines, and t½ against [A]₀ is a horizontal line because t½ is independent of [A]₀.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-electrochemistry-69", "question": "For the cell Sn | Sn²⁺ || Pb²⁺ | Pb, E°(Sn²⁺/Sn) = −0.14 V and E°(Pb²⁺/Pb) = −0.13 V. At 298 K the cell stops delivering current (E = 0) when the ratio [Pb²⁺]/[Sn²⁺] falls to about:", "options": ["2.18", "1.0", "0.46", "0.71"], "answer": 2, "explanation": "E°cell = −0.13 − (−0.14) = 0.01 V for Sn + Pb²⁺ → Sn²⁺ + Pb. E = 0.01 − (0.059/2) log([Sn²⁺]/[Pb²⁺]) = 0 gives log([Sn²⁺]/[Pb²⁺]) = 0.34, ratio 2.18, so [Pb²⁺]/[Sn²⁺] = 1/2.18 ≈ 0.46.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-electrochemistry-70", "question": "An uncatalysed reaction has Ea = 100 kJ mol⁻¹. In the presence of a catalyst the reaction at 300 K goes as fast as the uncatalysed reaction at 500 K. Assuming the frequency factor is unchanged, the activation energy of the catalysed reaction is:", "options": ["40 kJ mol⁻¹", "166.7 kJ mol⁻¹", "80 kJ mol⁻¹", "60 kJ mol⁻¹"], "answer": 3, "explanation": "Equal rate constants with equal A need equal Ea/RT: Ea(cat)/300 = 100/500, so Ea(cat) = 60 kJ mol⁻¹. 166.7 kJ inverts the ratio.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-electrochemistry-71", "question": "In the Leclanché (dry) cell, the substance that is reduced at the cathode is:", "options": ["MnO₂", "Zn", "NH₄⁺, giving H₂ gas", "ZnCl₂"], "answer": 0, "explanation": "Cathode: MnO₂ + NH₄⁺ + e⁻ → MnO(OH) + NH₃, so Mn goes from +4 to +3. Zinc (the container) is oxidised at the anode. Hydrogen gas is not evolved; that is exactly what the MnO₂ (a depolariser) prevents.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id":"chem-electrochemistry-72","question":"An H₂–O₂ fuel cell with an alkaline electrolyte delivers 2 faradays of charge. The amount of H₂ consumed is:","options":["0.5 mol","1 mol","4 mol","2 mol"],"answer":1,"explanation":"Anode: H₂ + 2OH⁻ → 2H₂O + 2e⁻, so 1 mol H₂ supplies 2 mol of electrons (2 F). At the cathode O₂ + 2H₂O + 4e⁻ → 4OH⁻ consumes 0.5 mol O₂ for the same charge, which is where the 0.5 trap comes from.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id": "chem-electrochemistry-73", "question": "According to the Arrhenius equation k = A e^(−Ea/RT), as the temperature tends to infinity the rate constant:", "options": ["also tends to infinity", "tends to zero", "tends to A", "tends to Ea/R"], "answer": 2, "explanation": "As T → ∞, Ea/RT → 0 and e^(−Ea/RT) → 1, so k → A, the pre-exponential (frequency) factor. A is the rate constant when every collision has enough energy, so k cannot grow without limit.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "chem-electrochemistry-74", "question": "A lead storage battery is discharged by a current of 2 A for 9650 s. The mass of H₂SO₄ consumed is (H₂SO₄ = 98 g/mol, F = 96 500 C/mol):", "options": ["9.8 g", "39.2 g", "4.9 g", "19.6 g"], "answer": 3, "explanation": "Charge = 19 300 C = 0.2 F. Overall: Pb + PbO₂ + 2H₂SO₄ → 2PbSO₄ + 2H₂O for 2 electrons, i.e. 1 mol H₂SO₄ per faraday (one consumed at each electrode). 0.2 mol × 98 = 19.6 g; counting only one electrode's sulphate gives 9.8 g.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "chem-electrochemistry-75", "question": "The mercury cell (Zn–Hg amalgam anode, HgO + carbon cathode, KOH/ZnO paste) gives an almost constant voltage of about 1.35 V throughout its life because:", "options": ["the overall cell reaction involves no ions in solution whose concentration changes", "zinc is continuously regenerated at the anode", "the electrolyte is a strong base that is never consumed in any step", "mercury has the highest standard reduction potential"], "answer": 0, "explanation": "Overall: Zn(Hg) + HgO(s) → ZnO(s) + Hg(l). Only solids and a pure liquid appear, so the Nernst reaction quotient is constant and E stays at E°. OH⁻ is consumed at one electrode but regenerated at the other, so it does not appear in the overall reaction.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "chem-electrochemistry-76", "question": "For O₂(g) + 4H⁺ + 4e⁻ → 2H₂O(l), E° = 1.23 V. At 298 K, the electrode potential at pH 7 with p(O₂) = 1 bar is about:", "options": ["1.23 V", "0.82 V", "1.64 V", "0.41 V"], "answer": 1, "explanation": "E = E° − (0.059/4) log(1/[H⁺]⁴) = 1.23 − 0.059 × pH = 1.23 − 0.413 = 0.817 V. The potential falls by 59 mV per pH unit; adding the correction gives 1.64 V, and 0.41 V is the correction alone.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "chem-electrochemistry-77", "question": "A zero-order reaction has a half-life of 10 min when the initial concentration is 0.4 M. If the initial concentration is 0.8 M, the time for the reaction to go to completion is:", "options": ["20 min", "10 min", "40 min", "80 min"], "answer": 2, "explanation": "For zero order t½ = [A]₀/2k, so k = 0.4/(2 × 10) = 0.02 M/min. Completion takes [A]₀/k = 0.8/0.02 = 40 min. 20 min is the new half-life, not the completion time.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"chem-electrochemistry-78","question":"Aqueous CuSO₄ is electrolysed between two copper electrodes. Which statement is correct?","options":["O₂ is evolved at the anode and the solution becomes acidic","The blue colour of the solution fades steadily","H₂ is evolved at the cathode","Copper dissolves at the anode, copper deposits at the cathode, and the Cu²⁺ concentration stays nearly constant"],"answer":3,"explanation":"With an active copper anode, Cu → Cu²⁺ + 2e⁻ is easier than oxidising water, and Cu²⁺ + 2e⁻ → Cu occurs at the cathode, so copper is merely transferred (the basis of electrorefining). O₂ evolution and fading colour happen only with inert (Pt) electrodes.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"chem-electrochemistry-79","question":"For a first-order reaction, the fraction of the reactant remaining after a time equal to the average life τ = 1/k is about:","options":["36.8%","63.2%","25%","50%"],"answer":0,"explanation":"[A]/[A]₀ = e^(−kt) = e^(−1) = 0.368 at t = 1/k. The average life is 1.44 t½, so more than half has reacted; 63.2% is the fraction that has reacted, the usual swap.","difficulty":"hard","source":"JEE Advanced pattern"},
  {"id":"chem-electrochemistry-80","question":"A conductivity cell of cell constant 1.5 cm⁻¹ filled with a 0.01 M solution of an electrolyte shows a resistance of 1500 Ω. The molar conductivity of the solution is:","options":["0.1 S cm² mol⁻¹","100 S cm² mol⁻¹","1 × 10⁻³ S cm² mol⁻¹","10 S cm² mol⁻¹"],"answer":1,"explanation":"κ = cell constant/R = 1.5/1500 = 1.0 × 10⁻³ S cm⁻¹. Λm = κ × 1000/c = 1.0 × 10⁻³ × 1000/0.01 = 100 S cm² mol⁻¹. Omitting the factor 1000 (mol/L → mol/cm³) gives 0.1.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "chem-electrochemistry-81", "question": "How many of the following statements about the Leclanché dry cell are correct? (A) The zinc container acts as the anode. (B) The cathode is a carbon (graphite) rod surrounded by powdered MnO₂ and carbon. (C) The electrolyte is a moist paste of NH₄Cl and ZnCl₂. (D) Its voltage (about 1.5 V) stays constant throughout its life.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and C are correct. D is false: the NH₃ formed at the cathode and the changing composition of the paste make the voltage fall gradually during use (unlike the mercury cell). Three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"chem-electrochemistry-82","question":"A lead storage battery is discharged until 0.1 F of charge has passed. The changes in mass of the positive (PbO₂) plate and of the negative (Pb) plate are respectively (Pb = 207, O = 16, S = 32):","options":["+4.8 g and +3.2 g","−3.2 g and +4.8 g","+3.2 g and +4.8 g","+6.4 g and +9.6 g"],"answer":2,"explanation":"Both plates turn into PbSO₄ (303). Positive: PbO₂ (239) → PbSO₄, +64 g per 2 F, so +3.2 g for 0.1 F. Negative: Pb (207) → PbSO₄, +96 g per 2 F, so +4.8 g. Both plates gain mass; using 1 F per mole gives the doubled values.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-electrochemistry-83", "question": "In a methane–oxygen fuel cell the overall reaction is CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l), with ΔG° = −818 kJ/mol. The standard EMF of the cell is about (F = 96 500 C/mol):", "options": ["4.24 V", "2.12 V", "0.53 V", "1.06 V"], "answer": 3, "explanation": "Carbon goes from −4 in CH₄ to +4 in CO₂, so n = 8 electrons per CH₄ (equivalently 2O₂ take 8 e⁻). E° = −ΔG°/nF = 818 000/(8 × 96 500) = 1.06 V. Taking n = 2 or 4 gives 4.24 V or 2.12 V.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"chem-electrochemistry-84","question":"Aqueous Na₂SO₄ is electrolysed between platinum electrodes with a current of 2 A for 965 s. The total volume of gas evolved (both electrodes, dry, at STP) is:","options":["0.336 L","0.112 L","0.224 L","0.448 L"],"answer":0,"explanation":"Charge = 1930 C = 0.02 F. Neither Na⁺ nor SO₄²⁻ is discharged; water is: cathode H₂ (2 F per mol) = 0.01 mol, anode O₂ (4 F per mol) = 0.005 mol. Total 0.015 mol × 22.4 = 0.336 L. Counting only H₂ gives 0.224 L.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-electrochemistry-85","question":"Given E°(Cu²⁺/Cu) = +0.34 V and E°(Cu⁺/Cu) = +0.52 V, the standard EMF for 2Cu⁺(aq) → Cu²⁺(aq) + Cu(s), and the behaviour of Cu⁺ in water, are:","options":["−0.36 V; Cu⁺ is stable","+0.36 V; Cu⁺ disproportionates","+0.18 V; Cu⁺ disproportionates","+0.86 V; Cu⁺ disproportionates"],"answer":1,"explanation":"Potentials are not additive; ΔG° values are: E°(Cu²⁺/Cu⁺) = 2(0.34) − 1(0.52) = 0.16 V. For the disproportionation, E° = E°(Cu⁺/Cu) − E°(Cu²⁺/Cu⁺) = 0.52 − 0.16 = +0.36 V > 0, so Cu⁺ is unstable in water. Subtracting 0.34 directly from 0.52 gives the 0.18 V trap.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-electrochemistry-86","question":"For consecutive first-order reactions A → B → C with k₁ = 0.2 min⁻¹ and k₂ = 0.1 min⁻¹, starting with pure A, the concentration of B is maximum at about:","options":["3.47 min","10 min","6.93 min","5 min"],"answer":2,"explanation":"[B] = k₁[A]₀(e^(−k₁t) − e^(−k₂t))/(k₂ − k₁); setting d[B]/dt = 0 gives t_max = ln(k₁/k₂)/(k₁ − k₂) = ln 2/0.1 = 6.93 min. 3.47 min is the half-life of A, a different quantity.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-electrochemistry-87", "question": "How many of the following statements are correct? (A) Decomposition of NH₃ on a hot platinum surface at high pressure is a zero-order reaction. (B) Radioactive decay follows first-order kinetics. (C) Acid-catalysed hydrolysis of an ester in a large excess of water is pseudo-first-order. (D) The order of a reaction can be zero or even fractional.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "A ✓ (the surface is saturated, so rate is independent of p(NH₃)); B ✓; C ✓ (water's concentration hardly changes); D ✓ (order is experimental, e.g. CH₃CHO decomposition has order 3/2). Only molecularity must be a whole number. All four.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"chem-electrochemistry-88","question":"The molar conductivity of 0.01 M acetic acid is 16.3 S cm² mol⁻¹ and its limiting molar conductivity is 390.5 S cm² mol⁻¹. The dissociation constant of acetic acid is about:","options":["1.7 × 10⁻⁵","4.2 × 10⁻²","1.7 × 10⁻³","1.8 × 10⁻⁵"],"answer":3,"explanation":"α = Λm/Λm° = 16.3/390.5 = 0.0417. Ka = cα²/(1 − α) = 0.01 × 0.00174/0.958 = 1.82 × 10⁻⁵. Dropping the (1 − α) term gives 1.74 × 10⁻⁵, and 4.2 × 10⁻² is α itself.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-electrochemistry-89", "question": "How many of the following statements about the corrosion of iron are correct? (A) Rusting is an electrochemical process in which iron acts as the anode. (B) Dissolved salts in water speed up rusting. (C) Rust is mainly Fe₃O₄. (D) A tin coating continues to protect iron even after it has been scratched.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "A ✓ and B ✓ (electrolytes raise conductivity). C is false: rust is hydrated ferric oxide, Fe₂O₃·xH₂O. D is false: tin is less reactive than iron, so once scratched iron becomes the anode and corrodes faster (zinc, being more reactive, would keep protecting it). Two are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"chem-electrochemistry-90","question":"A first-order reaction has a half-life of 10 min. The time taken for the reaction to go from 60% completion to 90% completion is:","options":["20 min","30 min","15 min","10 min"],"answer":0,"explanation":"At 60% completion 40% remains; at 90% completion 10% remains. Going from 40% to 10% is a fall by a factor of 4 = 2 half-lives = 20 min. Treating the 30% interval linearly is the trap.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-electrochemistry-91","question":"Fe²⁺ has to be titrated in a solution that also contains HCl. Which oxidant can oxidise Fe²⁺ but not Cl⁻ under standard conditions? (E°: Fe³⁺/Fe²⁺ = 0.77, Cl₂/Cl⁻ = 1.36, Br₂/Br⁻ = 1.09, MnO₄⁻/Mn²⁺ = 1.51, I₂/I⁻ = 0.54, Sn⁴⁺/Sn²⁺ = 0.15 V)","options":["KMnO₄","Br₂","I₂","Sn⁴⁺"],"answer":1,"explanation":"The oxidant's E° must lie above 0.77 V (to oxidise Fe²⁺) but below 1.36 V (not to oxidise Cl⁻): only Br₂ (1.09 V) fits. MnO₄⁻ also oxidises Cl⁻ to Cl₂, which is why KMnO₄ titrations of Fe²⁺ are not done in HCl; I₂ and Sn⁴⁺ are too weak.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-electrochemistry-92","question":"The rate constant of a first-order reaction is k = 2 × 10¹³ e^(−12000 K/T) s⁻¹. The temperature at which its half-life is 69.3 s is about:","options":["400 K","300 K","341 K","273 K"],"answer":2,"explanation":"t½ = 69.3 s gives k = 0.693/69.3 = 0.01 s⁻¹. e^(−12000/T) = 0.01/(2 × 10¹³) = 5 × 10⁻¹⁶, so 12000/T = 35.23 and T = 341 K (Ea = 12000 × 8.314 ≈ 99.8 kJ/mol).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-electrochemistry-93", "question": "The conductivity of a saturated solution of AgCl at 298 K is 1.86 × 10⁻⁶ S cm⁻¹, and that of the water used is 0.06 × 10⁻⁶ S cm⁻¹. If Λm°(AgCl) = 138.3 S cm² mol⁻¹, the Ksp of AgCl is about:", "options": ["1.8 × 10⁻⁵", "1.3 × 10⁻⁵", "1.81 × 10⁻¹⁰", "1.69 × 10⁻¹⁰"], "answer": 3, "explanation": "κ(AgCl) = 1.86 − 0.06 = 1.80 × 10⁻⁶ S cm⁻¹ (subtract the water). Solubility s = 1000κ/Λm° = 1.80 × 10⁻³/138.3 = 1.30 × 10⁻⁵ M, Ksp = s² = 1.69 × 10⁻¹⁰. Not subtracting the water gives 1.81 × 10⁻¹⁰; 1.3 × 10⁻⁵ is s, not Ksp.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"chem-electrochemistry-94","question":"The EMF of the cell Pt | H₂(1 bar) | HA(0.1 M) || H⁺(1 M) | H₂(1 bar) | Pt at 298 K is 0.177 V. The dissociation constant of the weak acid HA is about (2.303RT/F = 0.059 V):","options":["1 × 10⁻⁵","1 × 10⁻⁶","1 × 10⁻⁴","1 × 10⁻³"],"answer":0,"explanation":"E = 0.059 log([H⁺]cathode/[H⁺]anode) = 0.059 × pH(anode), so pH = 3 and [H⁺] = 10⁻³ M in the acid. Ka = (10⁻³)²/(0.1 − 0.001) ≈ 1 × 10⁻⁵. Taking [H⁺] itself as Ka gives 10⁻³.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-electrochemistry-95", "question": "The standard Gibbs energy of formation of Zn²⁺(aq) is −147 kJ/mol (with ΔfG° of H⁺(aq) taken as zero). The standard reduction potential E°(Zn²⁺/Zn) is about (F = 96 500 C/mol):", "options": ["+0.76 V", "−0.76 V", "−1.52 V", "−0.38 V"], "answer": 1, "explanation": "Zn²⁺ + 2e⁻ → Zn has ΔG° = 0 − (−147) = +147 kJ, so E° = −ΔG°/nF = −147 000/(2 × 96 500) = −0.76 V. Using ΔfG° itself as the reduction ΔG° gives +0.76 V, and n = 1 gives −1.52 V.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"chem-electrochemistry-96","question":"The quantity of electricity needed to reduce 1 mol of Cr₂O₇²⁻ completely to Cr³⁺ is:","options":["3 F","6 F","2 F","12 F"],"answer":1,"explanation":"Each Cr goes from +6 to +3, gaining 3 electrons, and there are two Cr atoms per dichromate ion, so 6 mol of electrons = 6 F are needed. 3 F counts only one chromium.","difficulty":"easy","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-97","question":"The rate law of a reaction is rate = k[A][B]². With concentrations in mol L⁻¹ and time in seconds, the unit of k is:","options":["L² mol⁻² s⁻¹","L mol⁻¹ s⁻¹","s⁻¹","mol L⁻¹ s⁻¹"],"answer":0,"explanation":"The overall order is 1 + 2 = 3. For order n, k has units (mol L⁻¹)^(1−n) s⁻¹, so for n = 3 the unit is L² mol⁻² s⁻¹.","difficulty":"easy","source":"NEET"},
  {"id":"chem-electrochemistry-98","question":"Given E° values: Ag⁺/Ag = +0.80 V, Fe³⁺/Fe²⁺ = +0.77 V, I₂/I⁻ = +0.54 V and Br₂/Br⁻ = +1.09 V. Which species can oxidise Fe²⁺ to Fe³⁺ under standard conditions?","options":["I₂","Fe³⁺","I⁻","Br₂"],"answer":3,"explanation":"An oxidant converts Fe²⁺ to Fe³⁺ only if its reduction potential exceeds 0.77 V. Br₂ (1.09 V) qualifies, giving E°cell = +0.32 V. I₂ (0.54 V) cannot; in fact Fe³⁺ oxidises I⁻ to I₂. (Ag⁺ at 0.80 V would also just work, but it is not offered.)","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-99","question":"For 2NO(g) + O₂(g) → 2NO₂(g), rate = k[NO]²[O₂]. If [NO] is doubled and [O₂] is halved at the same time, the rate becomes:","options":["4 times","the same","2 times","8 times"],"answer":2,"explanation":"New rate = k(2[NO])²(½[O₂]) = 4 × ½ × k[NO]²[O₂] = 2 times the original rate. Ignoring the halving of [O₂] gives 4 times.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-100","question":"At 298 K the limiting molar conductivities (S cm² mol⁻¹) of HCl, KCl and CH₃COOK are 425.9, 149.9 and 114.4 respectively. The limiting molar conductivity of CH₃COOH is:","options":["161.4 S cm² mol⁻¹","390.4 S cm² mol⁻¹","690.2 S cm² mol⁻¹","461.4 S cm² mol⁻¹"],"answer":1,"explanation":"By Kohlrausch's law, Λ°(CH₃COOH) = Λ°(HCl) + Λ°(CH₃COOK) − Λ°(KCl) = 425.9 + 114.4 − 149.9 = 390.4 S cm² mol⁻¹. The K⁺ and Cl⁻ contributions cancel out.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-101","question":"The elementary reaction 2NO(g) + O₂(g) → 2NO₂(g) occurs in a single step. Its molecularity and order are:","options":["Both 3","Molecularity 2, order 3","Molecularity 3, order 2","Both 2"],"answer":0,"explanation":"For an elementary step the molecularity equals the number of colliding species (2 NO + 1 O₂ = 3, termolecular), and the rate law follows the stoichiometry: rate = k[NO]²[O₂], third order. Order and molecularity coincide only for elementary steps.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-102","question":"A current of 0.50 A flows through a wire for 193 s. The number of electrons that pass any cross-section is about (F = 96500 C mol⁻¹, N_A = 6.022 × 10²³):","options":["6.0 × 10²³","1.0 × 10⁻³","3.0 × 10²⁰","6.0 × 10²⁰"],"answer":3,"explanation":"Q = It = 0.50 × 193 = 96.5 C = 96.5/96500 = 1.0 × 10⁻³ mol of electrons. Number = 10⁻³ × 6.022 × 10²³ ≈ 6.0 × 10²⁰. 1.0 × 10⁻³ is the amount in moles, not the number.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-electrochemistry-103","question":"For the cell Ni | Ni²⁺(0.001 M) || Ag⁺(0.01 M) | Ag at 298 K, given E°(Ni²⁺/Ni) = −0.25 V and E°(Ag⁺/Ag) = +0.80 V, the EMF is about:","options":["1.05 V","1.08 V","1.02 V","0.55 V"],"answer":2,"explanation":"Ni + 2Ag⁺ → Ni²⁺ + 2Ag, n = 2, E° = 0.80 − (−0.25) = 1.05 V. Q = [Ni²⁺]/[Ag⁺]² = 0.001/(0.01)² = 10, so E = 1.05 − (0.0591/2) log 10 = 1.02 V. Forgetting to square [Ag⁺] gives Q = 0.1 and 1.08 V.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-104","question":"The quantity of electricity needed to oxidise 1 mol of iron(II) oxalate, FeC₂O₄, completely to Fe³⁺ and CO₂ is:","options":["1 F","3 F","2 F","5 F"],"answer":1,"explanation":"Fe²⁺ → Fe³⁺ releases 1 electron, and C₂O₄²⁻ → 2CO₂ releases 2 electrons (each C goes +3 → +4). Total 3 mol electrons = 3 F per mole of FeC₂O₄. Counting only iron gives 1 F, only oxalate 2 F.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"chem-electrochemistry-105","question":"A cell reaction involving the transfer of 2 electrons has E°cell = 0.295 V at 298 K. Its equilibrium constant is (2.303RT/F = 0.059 V):","options":["1 × 10¹⁰","1 × 10⁵","1 × 10²⁰","1 × 10⁻¹⁰"],"answer":0,"explanation":"log K = nE°/0.059 = 2 × 0.295/0.059 = 10, so K = 10¹⁰. Forgetting n gives 10⁵. A positive E° always corresponds to K > 1.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-106","question":"When an aqueous solution of a strong electrolyte is diluted, how do its conductivity (κ) and molar conductivity (Λm = κ/c) change?","options":["κ increases, Λm decreases","Both increase","Both decrease","κ decreases, Λm increases"],"answer":3,"explanation":"κ is the conductance of a unit cube of solution, so it falls as the number of ions per unit volume falls. Λm refers to one mole of electrolyte; on dilution inter-ionic attraction weakens and the ions move more freely, so Λm rises (approaching Λ°m).","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-107","question":"A reaction has an activation energy of 50 kJ mol⁻¹. By roughly what factor does its rate constant increase when the temperature is raised from 300 K to 350 K? (R = 8.314 J K⁻¹ mol⁻¹)","options":["1.2","2.9","17.5","6.0"],"answer":2,"explanation":"ln(k₂/k₁) = (Ea/R)(1/T₁ − 1/T₂) = (50000/8.314)(1/300 − 1/350) = 6014 × 4.76 × 10⁻⁴ = 2.86, so k₂/k₁ = e²·⁸⁶ ≈ 17.5. 2.9 is the natural logarithm, not the ratio.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-108","question":"The gas-phase first-order decomposition A(g) → B(g) + C(g) is started with pure A at 200 mm Hg in a closed vessel at constant temperature. After 10 min the total pressure is 300 mm Hg. The rate constant is about:","options":["0.0405 min⁻¹","0.0693 min⁻¹","0.1099 min⁻¹","0.0288 min⁻¹"],"answer":1,"explanation":"If A falls by x, total pressure = 200 + x, so x = 100 mm and p(A) = 100 mm: exactly half of A has reacted in 10 min. So t½ = 10 min and k = 0.693/10 = 0.0693 min⁻¹. Using p_total = 300 mm as the remaining A gives a negative logarithm, not a rate constant.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"chem-electrochemistry-109","question":"A platinum wire dips into a solution in which [Fe³⁺]/[Fe²⁺] = 100. Given E°(Fe³⁺/Fe²⁺) = 0.77 V, the electrode potential at 298 K is about:","options":["0.89 V","0.65 V","0.83 V","0.77 V"],"answer":0,"explanation":"Fe³⁺ + e⁻ → Fe²⁺ (n = 1): E = 0.77 − 0.0591 log([Fe²⁺]/[Fe³⁺]) = 0.77 + 0.0591 × 2 = 0.89 V. A higher proportion of the oxidised form raises the reduction potential; inverting the ratio gives 0.65 V.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-110","question":"A hydrogen electrode (p(H₂) = 1 bar) is dipped in a solution of pH 3 at 298 K. Its reduction potential is about:","options":["0.000 V","+0.177 V","−0.059 V","−0.177 V"],"answer":3,"explanation":"For 2H⁺ + 2e⁻ → H₂, E = 0 − (0.0591/2) log(p(H₂)/[H⁺]²) = −0.0591 × pH = −0.177 V. The potential becomes more negative as the solution becomes less acidic.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-111","question":"The same quantity of charge is passed through two cells in series containing aqueous AgNO₃ and aqueous CuSO₄. If 1.08 g of silver is deposited, the mass of copper deposited is (Ag = 108, Cu = 63.5):","options":["0.635 g","0.159 g","0.318 g","1.08 g"],"answer":2,"explanation":"1.08 g Ag = 0.01 mol = 0.01 F. The same 0.01 F deposits 0.005 mol Cu (2e⁻ per Cu²⁺) = 0.318 g. This is Faraday's second law: masses deposited are proportional to equivalent masses (108 : 31.75).","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-112","question":"The acid-catalysed hydrolysis of ethyl acetate in a large excess of water follows first-order kinetics. This is because:","options":["The H⁺ catalyst is consumed during the reaction","The concentration of water hardly changes, so it is absorbed into the observed rate constant","The molecularity of the reaction is one","Water does not take part in the rate-determining step"],"answer":1,"explanation":"The true rate law is rate = k[ester][H₂O][H⁺]; with water in huge excess and H⁺ regenerated, both stay effectively constant, so rate = k′[ester] — pseudo-first-order. Water does participate, and the elementary step is bimolecular.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-113","question":"The temperature coefficient of a reaction is 3. If the temperature is raised from 300 K to 330 K, the rate increases by a factor of about:","options":["27","30","9","3"],"answer":0,"explanation":"A 30 K rise is three 10-K intervals, so the rate is multiplied by 3³ = 27. Adding (3 × 3 = 9 or 3 × 10 = 30) instead of compounding is the usual mistake.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-114","question":"The limiting ionic conductivities of Al³⁺ and SO₄²⁻ are 189 and 160 S cm² mol⁻¹ respectively. The limiting molar conductivity of Al₂(SO₄)₃ is:","options":["349 S cm² mol⁻¹","698 S cm² mol⁻¹","1047 S cm² mol⁻¹","858 S cm² mol⁻¹"],"answer":3,"explanation":"Λ°m = ν₊λ°₊ + ν₋λ°₋ = 2 × 189 + 3 × 160 = 378 + 480 = 858 S cm² mol⁻¹. Adding the two ionic values once each gives 349.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-115","question":"Brine (aqueous NaCl, 1 L) is electrolysed with inert electrodes by a current of 5 A for 1930 s, and the cathode and anode products are kept apart. Assuming 100% efficiency and no volume change, the pH of the solution afterwards is:","options":["7","14","13","12"],"answer":2,"explanation":"Charge = 5 × 1930 = 9650 C = 0.1 F. At the cathode 2H₂O + 2e⁻ → H₂ + 2OH⁻, so 0.1 mol OH⁻ forms in 1 L: pOH = 1, pH = 13. Meanwhile 0.05 mol Cl₂ is released at the anode.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-116","question":"Given E°(MnO₄⁻/Mn²⁺) = 1.51 V and E°(MnO₂/Mn²⁺) = 1.23 V, the standard potential E°(MnO₄⁻/MnO₂) is about:","options":["1.37 V","1.70 V","0.28 V","2.74 V"],"answer":1,"explanation":"Potentials are not additive, but ΔG° values are. ΔG° = −nFE°: MnO₄⁻ → Mn²⁺ (n = 5) = MnO₄⁻ → MnO₂ (n = 3) + MnO₂ → Mn²⁺ (n = 2). So 3E° = 5(1.51) − 2(1.23) = 5.09, giving E° = 1.70 V. Simple subtraction gives 0.28 V.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-electrochemistry-117","question":"For Cr₂O₇²⁻ + 14H⁺ + 6e⁻ → 2Cr³⁺ + 7H₂O, E° = 1.33 V. At 298 K the potential of this half-cell with [Cr₂O₇²⁻] = [Cr³⁺] = 1 M but pH = 3 is about:","options":["0.92 V","1.29 V","1.15 V","0.50 V"],"answer":0,"explanation":"E = E° − (0.0591/6) log([Cr³⁺]²/([Cr₂O₇²⁻][H⁺]¹⁴)) = 1.33 − (0.0591/6)(42) = 1.33 − 0.41 = 0.92 V. The fourteenth power of [H⁺] makes dichromate a much weaker oxidant in less acidic solution.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-electrochemistry-118","question":"The concentration cell Ag | Ag⁺(saturated AgCl solution) || Ag⁺(0.10 M) | Ag has an EMF of 0.236 V at 298 K. The Ksp of AgCl is about (2.303RT/F = 0.0591 V):","options":["1.0 × 10⁻¹²","1.0 × 10⁻⁸","1.0 × 10⁻⁵","1.0 × 10⁻¹⁰"],"answer":3,"explanation":"E = 0.0591 log(0.10/[Ag⁺]sat), so log(0.10/[Ag⁺]) = 3.99 and [Ag⁺]sat ≈ 1.0 × 10⁻⁵ M. In pure saturated AgCl, [Ag⁺] = [Cl⁻] = s, so Ksp = s² ≈ 1.0 × 10⁻¹⁰. Reporting s itself gives 10⁻⁵.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-electrochemistry-119","question":"For a second-order reaction with rate = k[A]², the ratio of the time required for 87.5% completion to the time required for 50% completion is:","options":["8","3","7","4"],"answer":2,"explanation":"Integrated law: 1/[A] − 1/[A]₀ = kt. For 50%: t = 1/(k[A]₀). For 87.5%, [A] = [A]₀/8: t = 7/(k[A]₀). Ratio = 7. For a first-order reaction the same ratio is 3 (three half-lives).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-electrochemistry-120","question":"Chromium is plated from an acidified CrO₃ (Cr⁶⁺) bath with only 30% current efficiency. A current of 10 A is passed for 1 hour (Cr = 52). The mass of chromium deposited is about:","options":["3.23 g","0.97 g","1.94 g","2.91 g"],"answer":1,"explanation":"Total charge = 36000 C; useful charge = 0.30 × 36000 = 10800 C = 0.1119 F. Cr⁶⁺ → Cr needs 6 e⁻, so Cr = 0.01865 mol = 0.97 g. Using 100% efficiency gives 3.23 g, and taking Cr³⁺ (n = 3) gives 1.94 g.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-electrochemistry-121","question":"Dilute aqueous H₂SO₄ is electrolysed with platinum electrodes using 0.5 F of charge. The total volume of gas (both electrodes) collected at STP is about:","options":["8.4 L","11.2 L","16.8 L","5.6 L"],"answer":0,"explanation":"At the cathode 0.5 F gives 0.25 mol H₂ (2e⁻ each); at the anode 2H₂O → O₂ + 4H⁺ + 4e⁻ gives 0.125 mol O₂. Total 0.375 mol × 22.4 = 8.4 L. 5.6 L counts only H₂.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-122","question":"Given E°(Fe³⁺/Fe²⁺) = 0.77 V and E°(Ag⁺/Ag) = 0.80 V, the equilibrium constant at 298 K for Fe³⁺(aq) + Ag(s) ⇌ Fe²⁺(aq) + Ag⁺(aq) is about:","options":["1.0 × 10⁻³","3.2","1.0","0.31"],"answer":3,"explanation":"E°cell = E°(Fe³⁺/Fe²⁺) − E°(Ag⁺/Ag) = 0.77 − 0.80 = −0.03 V with n = 1. log K = −0.03/0.0591 = −0.51, so K ≈ 0.31. The reaction is only slightly unfavourable, so appreciable amounts of all species coexist.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-electrochemistry-123","question":"The molar conductivity of a strong electrolyte is 124 S cm² mol⁻¹ at 0.01 M and 118 S cm² mol⁻¹ at 0.04 M. Assuming Λm = Λ°m − A√c holds, Λ°m is:","options":["126 S cm² mol⁻¹","136 S cm² mol⁻¹","130 S cm² mol⁻¹","128 S cm² mol⁻¹"],"answer":2,"explanation":"√c = 0.1 and 0.2. Then 124 = Λ° − 0.1A and 118 = Λ° − 0.2A give A = 60 and Λ°m = 130 S cm² mol⁻¹. Extrapolating linearly in c (not √c) gives 126.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-electrochemistry-124","question":"The proposed mechanism for 2NO + O₂ → 2NO₂ is: 2NO ⇌ N₂O₂ (fast equilibrium, constant K) followed by N₂O₂ + O₂ → 2NO₂ (slow, rate constant k). The rate law and overall order are:","options":["rate = kK[NO][O₂], order 2","rate = kK[NO]²[O₂], order 3","rate = k[NO]², order 2","rate = k[N₂O₂][O₂], order 2"],"answer":1,"explanation":"The slow step gives rate = k[N₂O₂][O₂]. Intermediates cannot appear in the final rate law, so substitute [N₂O₂] = K[NO]² from the fast equilibrium: rate = kK[NO]²[O₂], third order overall.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-electrochemistry-125","question":"The rate constant of a reaction obeys log k = 14.34 − (1.25 × 10⁴ K)/T. Its activation energy is about (R = 8.314 J K⁻¹ mol⁻¹):","options":["239 kJ mol⁻¹","104 kJ mol⁻¹","12.5 kJ mol⁻¹","286 kJ mol⁻¹"],"answer":0,"explanation":"Arrhenius in log₁₀ form: log k = log A − Ea/(2.303RT). So Ea/(2.303R) = 1.25 × 10⁴ K and Ea = 2.303 × 8.314 × 1.25 × 10⁴ ≈ 239 kJ mol⁻¹. Omitting the 2.303 gives 104 kJ mol⁻¹.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-electrochemistry-126","question":"For A + B → products, initial rates (mol L⁻¹ s⁻¹) are: [A] = 0.1, [B] = 0.1 → 2 × 10⁻³; [A] = 0.2, [B] = 0.1 → 8 × 10⁻³; [A] = 0.1, [B] = 0.3 → 6 × 10⁻³. The initial rate when [A] = 0.3 M and [B] = 0.2 M is:","options":["1.2 × 10⁻²","1.8 × 10⁻²","7.2 × 10⁻²","3.6 × 10⁻²"],"answer":3,"explanation":"Doubling [A] quadruples the rate (second order in A); tripling [B] triples it (first order in B). k = 2 × 10⁻³/(0.1² × 0.1) = 2 L² mol⁻² s⁻¹. Rate = 2 × 0.3² × 0.2 = 3.6 × 10⁻² mol L⁻¹ s⁻¹. Treating A as first order gives 1.2 × 10⁻².","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-127","question":"How many of the following statements are correct? (A) In a galvanic cell, electrons flow in the external circuit from anode to cathode. (B) The salt bridge allows electrons to move between the two half-cells. (C) Molar conductivity of a weak electrolyte rises steeply on dilution because its degree of dissociation increases. (D) The cell potential is an extensive property that doubles when the cell equation is doubled. (E) A cell whose ΔG is negative has a positive EMF.","options":["Only two","Only three","Only four","All five"],"answer":1,"explanation":"(A), (C) and (E) are correct. (B) is false: the salt bridge carries ions, not electrons. (D) is false: E is intensive; doubling the equation doubles ΔG and n but leaves E unchanged. Three statements are correct.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-electrochemistry-128","question":"For Cl₂(g) + 2e⁻ → 2Cl⁻(aq), E° = 1.36 V. The potential of this electrode at 298 K with p(Cl₂) = 1 bar and [Cl⁻] = 0.1 M is about:","options":["1.36 V","1.30 V","1.42 V","1.39 V"],"answer":2,"explanation":"E = E° − (0.0591/2) log([Cl⁻]²/p(Cl₂)) = 1.36 − 0.02955 × (−2) = 1.36 + 0.059 = 1.42 V. Forgetting to square [Cl⁻] gives 1.39 V, and a sign error gives 1.30 V.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-electrochemistry-129","question":"Given E° values: Mg²⁺/Mg = −2.37 V, Zn²⁺/Zn = −0.76 V, Fe²⁺/Fe = −0.44 V, Ni²⁺/Ni = −0.25 V, Cu²⁺/Cu = +0.34 V, Ag⁺/Ag = +0.80 V. Which metal can reduce Cu²⁺ ions to copper under standard conditions but cannot reduce Fe²⁺ ions to iron?","options":["Ni","Zn","Mg","Ag"],"answer":0,"explanation":"A metal reduces a cation only if its own E° is lower. Ni (−0.25 V) is below Cu (+0.34 V) but above Fe (−0.44 V), so it reduces Cu²⁺ but not Fe²⁺. Zn and Mg reduce both, and Ag reduces neither.","difficulty":"very-hard","source":"JEE Main · NEET"},
];

